package ir.zagroserp.pda.domain.alerts

import ir.zagroserp.pda.core.JalaliDate
import ir.zagroserp.pda.domain.model.PendingQueueSummary

/**
 * An alert generated by the app itself, as opposed to a notification pushed by the server.
 * [id] is deterministic so re-evaluating the same condition updates the existing row instead of
 * creating a duplicate.
 */
data class SystemAlertSpec(
    val id: String,
    val title: String,
    val body: String,
    val type: String,
)

/**
 * Turns the offline queue state into actionable alerts.
 *
 * Pure and side-effect free so it can be unit tested: this is what decides whether the visitor is
 * warned that their orders are not reaching the server.
 */
object SystemAlerts {

    /**
     * Derived alerts: recomputed on every queue change, so they disappear when the condition
     * clears. Kept under their own prefix because reconciliation deletes anything in this
     * namespace that is no longer wanted.
     */
    const val PREFIX = "local-alert-"

    /**
     * Records of queue entries the server permanently refused. These are **not** reconciled —
     * they stay until the visitor acknowledges them, because they represent work that was lost.
     */
    const val PREFIX_REJECTED = "local-rejected-"

    /** Every locally generated message shares this root, used by the unread-alert query. */
    const val LOCAL_ROOT = "local-"

    const val TYPE_QUEUE_FAILED = "SYSTEM_QUEUE_FAILED"
    const val TYPE_QUEUE_PENDING = "SYSTEM_QUEUE_PENDING"
    const val TYPE_QUEUE_REJECTED = "SYSTEM_QUEUE_REJECTED"

    const val ID_FAILED_ORDERS = "${PREFIX}failed-orders"
    const val ID_PENDING_ORDERS = "${PREFIX}pending-orders"
    const val ID_PENDING_VISITS = "${PREFIX}pending-visits"
    const val ID_PENDING_LOCATIONS = "${PREFIX}pending-locations"

    /** A handful of queued items is normal while offline; these are the "something is wrong" levels. */
    const val PENDING_ORDERS_THRESHOLD = 5
    const val PENDING_VISITS_THRESHOLD = 20
    const val PENDING_LOCATIONS_THRESHOLD = 100

    fun isSystemAlert(id: String): Boolean = id.startsWith(LOCAL_ROOT)

    fun visitRejectionId(clientVisitId: String): String = "${PREFIX_REJECTED}visit-$clientVisitId"

    fun orderRejectionId(clientOrderId: String): String = "${PREFIX_REJECTED}order-$clientOrderId"

    /** Alert raised when a queued entry is dropped because the server will never accept it. */
    fun rejected(
        id: String,
        kind: String,
        subject: String,
        reason: String,
    ): SystemAlertSpec = SystemAlertSpec(
        id = id,
        title = "$kind ثبت نشد",
        body = buildString {
            if (subject.isNotBlank()) append("$subject — ")
            append(reason)
            append(" این مورد از صف ارسال حذف شد؛ لطفاً دوباره و در محل مشتری تلاش کنید.")
        },
        type = TYPE_QUEUE_REJECTED,
    )

    fun derive(summary: PendingQueueSummary): List<SystemAlertSpec> = buildList {
        if (summary.failedOrders > 0) {
            add(
                SystemAlertSpec(
                    id = ID_FAILED_ORDERS,
                    title = "سفارش‌های ناموفق در ارسال",
                    body = "${fa(summary.failedOrders)} سفارش پس از تلاش مجدد هم ارسال نشد. " +
                        "برای بررسی به سابقه‌ی سفارش‌ها مراجعه کنید.",
                    type = TYPE_QUEUE_FAILED,
                ),
            )
        }

        if (summary.orders >= PENDING_ORDERS_THRESHOLD) {
            add(
                SystemAlertSpec(
                    id = ID_PENDING_ORDERS,
                    title = "سفارش‌های در انتظار ارسال",
                    body = "${fa(summary.orders)} سفارش در صف است و هنوز به سرور نرسیده.",
                    type = TYPE_QUEUE_PENDING,
                ),
            )
        }

        if (summary.visits >= PENDING_VISITS_THRESHOLD) {
            add(
                SystemAlertSpec(
                    id = ID_PENDING_VISITS,
                    title = "بازدیدهای در انتظار ارسال",
                    body = "${fa(summary.visits)} بازدید در صف است. اتصال اینترنت را بررسی کنید.",
                    type = TYPE_QUEUE_PENDING,
                ),
            )
        }

        if (summary.locations >= PENDING_LOCATIONS_THRESHOLD) {
            add(
                SystemAlertSpec(
                    id = ID_PENDING_LOCATIONS,
                    title = "موقعیت‌های در انتظار ارسال",
                    body = "${fa(summary.locations)} نقطه‌ی موقعیت ارسال نشده است.",
                    type = TYPE_QUEUE_PENDING,
                ),
            )
        }
    }

    private fun fa(value: Int): String = JalaliDate.toPersianDigits(value.toString())
}
